/**
 * Generated by scaffold-test-specs from MODULE_PLAN.yaml auth: section.
 *
 * Endpoints under test (canonical auth module):
 *   POST   /api/auth/signup    — public, registers new user
 *   POST   /api/auth/login     — public, returns httpOnly cookies
 *   POST   /api/auth/refresh   — public (cookie-bound), rotates tokens
 *   POST   /api/auth/logout    — clears cookies (RemoveTokenInterceptor)
 *   GET    /api/auth/me        — authenticated, returns current user
 *
 * Test coverage:
 *   - signup happy path (201)
 *   - signup with duplicate identifier → 409
 *   - login with valid creds (200 + Set-Cookie)
 *   - login with wrong password (401)
 *   - me with cookie (200)
 *   - me without cookie (401)
 *   - logout (204)
 */
import supertest from 'supertest';
import {
  createTestApp,
  closeTestApp,
  type TestAppContext,
} from '../setup/test-app.factory';
import { cleanDatabase } from '../setup/test-database';

describe('Auth E2E', () => {
  let ctx: TestAppContext;

  beforeAll(async () => {
    ctx = await createTestApp();
  });

  beforeEach(async () => {
    await cleanDatabase(ctx.dataSource);
  });

  afterAll(async () => {
    await closeTestApp(ctx);
  });

  describe('POST /api/auth/signup', () => {
    it('returns 201 (or 200) on valid signup', async () => {
      await supertest(ctx.app.getHttpServer())
        .post('/api/auth/signup')
        .send({
          fullName: 'spec-fullName',
          email: 'auth-spec@test.com',
          password: 'TestPass1!',
          role: 0,
        })
        .expect((res) => {
          if (![200, 201].includes(res.status)) {
            throw new Error(`Expected 200/201 on signup, got ${res.status}: ${JSON.stringify(res.body).slice(0, 200)}`);
          }
        });
    });

    it('rejects duplicate email with 409 (or 400)', async () => {
      const body = {
          fullName: 'spec-fullName',
          email: 'auth-spec@test.com',
          password: 'TestPass1!',
          role: 0,
      };
      await supertest(ctx.app.getHttpServer()).post('/api/auth/signup').send(body);
      await supertest(ctx.app.getHttpServer())
        .post('/api/auth/signup')
        .send(body)
        .expect((res) => {
          if (![400, 409, 422].includes(res.status)) {
            throw new Error(`Expected 409 on duplicate signup, got ${res.status}`);
          }
        });
    });

    it('rejects empty body with 400/422', async () => {
      await supertest(ctx.app.getHttpServer())
        .post('/api/auth/signup')
        .send({})
        .expect((res) => {
          if (![400, 422].includes(res.status)) {
            throw new Error(`Expected 400/422 on empty signup, got ${res.status}`);
          }
        });
    });
  });

  describe('POST /api/auth/login', () => {
    it('returns 200 + Set-Cookie on valid creds', async () => {
      // pre-register
      await supertest(ctx.app.getHttpServer())
        .post('/api/auth/signup')
        .send({
          fullName: 'spec-fullName',
          email: 'auth-spec@test.com',
          password: 'TestPass1!',
          role: 0,
        });
      const res = await supertest(ctx.app.getHttpServer())
        .post('/api/auth/login')
        .send({ email: 'auth-spec@test.com', password: 'TestPass1!' });
      if (res.status !== 200) {
        throw new Error(`Expected 200 on login, got ${res.status}: ${JSON.stringify(res.body).slice(0, 200)}`);
      }
      const cookies = res.headers['set-cookie'];
      if (!cookies || (Array.isArray(cookies) ? cookies.length : 0) === 0) {
        throw new Error('Expected Set-Cookie header on login (access_token/refresh_token)');
      }
    });

    it('returns 401 on wrong password', async () => {
      await supertest(ctx.app.getHttpServer())
        .post('/api/auth/login')
        .send({ email: 'nonexistent@test.com', password: 'WrongPass1!' })
        .expect(401);
    });
  });

  describe('GET /api/auth/me', () => {
    it('returns 401 without cookie', async () => {
      await supertest(ctx.app.getHttpServer())
        .get('/api/auth/me')
        .expect(401);
    });

    it('returns 200 with valid cookie', async () => {
      // signup + login to obtain cookie
      await supertest(ctx.app.getHttpServer())
        .post('/api/auth/signup')
        .send({
          fullName: 'spec-fullName',
          email: 'auth-spec@test.com',
          password: 'TestPass1!',
          role: 0,
        });
      const loginRes = await supertest(ctx.app.getHttpServer())
        .post('/api/auth/login')
        .send({ email: 'auth-spec@test.com', password: 'TestPass1!' });
      const raw = loginRes.headers['set-cookie'];
      const cookie = Array.isArray(raw) ? raw.map((c: string) => c.split(';')[0]).join('; ') : (raw || '');

      await supertest(ctx.app.getHttpServer())
        .get('/api/auth/me')
        .set('Cookie', cookie)
        .expect(200);
    });
  });

  describe('POST /api/auth/logout', () => {
    it('returns 200/204 (logout is @Public; clears cookies via interceptor)', async () => {
      await supertest(ctx.app.getHttpServer())
        .post('/api/auth/logout')
        .send({})
        .expect((res) => {
          if (![200, 204].includes(res.status)) {
            throw new Error(`Expected 200/204 on logout, got ${res.status}`);
          }
        });
    });
  });
});
